// Static competitor URL list keyed to Krish's live B2C product portfolio
// gutted, merciless, onalert retired from OS control plane 2026-07-06 (directive) — entries removed
// Same list as Maya's old Comp Prep, plus a few additions
const targets = [
  // Fractionl Circle competitors (CRM / network tools)
  { url: 'https://getdex.com', product: 'circle', name: 'Dex' },
  { url: 'https://clay.com', product: 'circle', name: 'Clay' },
  { url: 'https://folk.app', product: 'circle', name: 'Folk' },
  // TODO: add Plinth (typed product-data API+MCP for agents) competitor set here once a real,
  // verified competitor list is researched. Do not invent URLs/names.
  // TODO: add Full Time (daily AI football recap) competitor set here once a real,
  // verified competitor list is researched. Do not invent URLs/names.
];
return targets.map(t => ({ json: t }));

// Compute content hash + extract metadata + prep row for insert
const crypto = require('crypto');
const out = [];
const responses = $input.all();
const targets = $('Build Target List').all();

for (let i = 0; i < responses.length; i++) {
  const r = responses[i].json || {};
  const target = targets[i]?.json || {};
  const body = r.body || '';
  const status = r.statusCode || 0;
  const bodyStr = typeof body === 'string' ? body : JSON.stringify(body || '');

  // Strip common dynamic content that would falsely trigger changes: timestamps, CSRF tokens, random nonces
  let normalized = bodyStr
    .replace(/<meta[^>]+(?:csrf|nonce|timestamp)[^>]*>/gi, '')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')  // strip all scripts
    .replace(/"[a-f0-9]{32,}"/gi, '')  // strip long hex strings (hashes/tokens)
    .replace(/\d{10,}/g, '');  // strip unix timestamps

  const hash = crypto.createHash('sha256').update(normalized).digest('hex');

  // Extract title + meta description for human-readable diff
  const titleMatch = bodyStr.match(/<title[^>]*>([^<]+)<\/title>/i);
  const metaMatch = bodyStr.match(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']+)["']/i);

  out.push({
    json: {
      competitor_url: target.url,
      competitor_name: target.name || null,
      product: target.product || null,
      http_status: status,
      response_time_ms: null,
      content_hash: hash,
      content_length: bodyStr.length,
      title: titleMatch ? titleMatch[1].slice(0, 300) : null,
      meta_description: metaMatch ? metaMatch[1].slice(0, 500) : null,
      change_detected: false,  // fill in next step
      change_summary: null,
      checked_at: new Date().toISOString()
    }
  });
}
return out;

// For each new row, compare hash to prior row. Set change_detected + summary.
const currents = $('Hash + Metadata').all();
const priors = $input.all();
const out = [];

for (let i = 0; i < currents.length; i++) {
  const cur = currents[i].json;
  const priorRows = Array.isArray(priors[i]?.json) ? priors[i].json : [];
  const prior = priorRows[0];

  let changed = false;
  let summary = null;

  if (!prior) {
    summary = 'first check';
  } else if (prior.content_hash !== cur.content_hash) {
    changed = true;
    const bits = [];
    if (prior.title !== cur.title) bits.push('title changed');
    if (prior.meta_description !== cur.meta_description) bits.push('description changed');
    if (bits.length === 0) bits.push('content changed');
    summary = bits.join('; ');
  } else {
    summary = 'no change';
  }

  out.push({ json: { ...cur, change_detected: changed, change_summary: summary } });
}
return out;

